query FindManyProjects($filter: ProjectFilterInput, $orderBy: [ProjectOrderByInput], $lastCursor: String, $limit: Int, $offset: Int) {
  projects(
    filter: $filter
    orderBy: $orderBy
    first: $limit
    after: $lastCursor
    offset: $offset
  ) {
    edges {
      node {
        __typename
        aliases
        budget
        code
        contactEmails {
          primaryEmail
          additionalEmails
          __typename
        }
        cost {
          amountMicros
          currencyCode
          __typename
        }
        createdAt
        createdBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        deletedAt
        documents {
          fileId
          label
          extension
          url
          __typename
        }
        dueDate
        hotline {
          primaryPhoneNumber
          primaryPhoneCountryCode
          primaryPhoneCallingCode
          additionalPhones {
            number
            callingCode
            countryCode
            __typename
          }
          __typename
        }
        id
        isActive
        kickoffAt
        leadId
        name
        phase
        position
        priority
        settingsJson
        siteAddress {
          addressStreet1
          addressStreet2
          addressCity
          addressState
          addressCountry
          addressPostcode
          addressLat
          addressLng
          __typename
        }
        sponsorName {
          firstName
          lastName
          __typename
        }
        summary {
          blocknote
          markdown
          tiptap
          __typename
        }
        tags
        updatedAt
        updatedBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        website {
          primaryLinkUrl
          primaryLinkLabel
          secondaryLinks {
            label
            url
            __typename
          }
          __typename
        }
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
